            new Quote { Id = "https://fr.wikiquote.org/wiki/Stendhal", Text = "Nous avouerons que notre héros était fort peu héros en ce moment. Toutefois, la peur ne venait chez lui qu’en seconde ligne ; il était surtout scandalisé de ce bruit qui lui faisait mal aux oreilles.", Author = "Stendhal" },
